        diagNodeParentAtBlur.set(resolvedTarget, { parent: resolvedTarget.parentElement || null });
        diagShortsBlurStackLog('overlay_reresolve_after_apply', resolvedTarget, src, 'reason=' + (reason || 'unknown'));
